import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        StringBuilder left = new StringBuilder(), middle = new StringBuilder();
        for (int c = 0; c < 26; c++) {
            for (int k = 0; k < counts[c] / 2; k++) left.append((char) ('a' + c));
            if (counts[c] % 2 == 1) middle.append((char) ('a' + c));
        }
        String l = left.toString();
        System.out.println(l + middle + left.reverse());
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s := readToken()
	var counts [26]int
	for i := 0; i < len(s); i++ {
		counts[s[i]-'a']++
	}
	var left, middle []byte
	for c := 0; c < 26; c++ {
		for k := 0; k < counts[c]/2; k++ {
			left = append(left, byte('a'+c))
		}
		if counts[c]%2 == 1 {
			middle = append(middle, byte('a'+c))
		}
	}
	out := append(append([]byte{}, left...), middle...)
	for i := len(left) - 1; i >= 0; i-- {
		out = append(out, left[i])
	}
	fmt.Println(string(out))
}
